export type PersonalAccessTokenConnectionPayload = {
    customUrl?: string | undefined;
    token: string;
    name: string;
};
export type AzurePersonalAccessTokenConnectionPayload = PersonalAccessTokenConnectionPayload & {
    organization: string;
};
export type CreateAuthenticationTokenPayload = {
    id: string;
    name: string;
    createdAt: string;
    scope?: string;
    token: string;
};
export type AuthenticationTokenPayload = Omit<CreateAuthenticationTokenPayload, "token">;
export type AuthenticationTokens = Array<AuthenticationTokenPayload>;
